import { Navigate, Outlet } from "react-router-dom";
import DasRightSectionPage from "../admin/daseBoardRightSection/DasBoardRightSection";
import { isTokenExpiredMidnight } from "../../httpInterSeptur/HttpInterSeptur";

function PrivateRoute({ component: component, tokenNoti, walletData, services, setProfileData, isInstantpaypresnt }) {
    const token = window.localStorage.getItem('userIdToken') || window.localStorage.getItem('userToken');
    if (token && isTokenExpiredMidnight(token)) {
        window.localStorage.clear();
        window.sessionStorage.clear();
        return <Navigate to='/login-area' replace />;
    }
    return token ? (
        <DasRightSectionPage
            tokenNoti={tokenNoti}
            walletData={walletData}
            PrivateRoute={PrivateRoute}
            services={services}
            setProfileData={setProfileData}
            isInstantpaypresnt={isInstantpaypresnt}
        />
    ) : (
        <Navigate to='/login-area' replace />
    );
}

export default PrivateRoute;
